import itertools

def construct(n):
    if n == 1:
        return "1"
    
    # Generate permutations in the recursive insertion order
    # P_1 = [(1,)]
    # P_{k+1} is generated by inserting k+1 into each permutation of P_k at all positions
    
    perms = [(1,)]
    for k in range(2, n + 1):
        new_perms = []
        for p in perms:
            # Insert k into p at every possible position
            for i in range(len(p) + 1):
                new_p = p[:i] + (k,) + p[i:]
                new_perms.append(new_p)
        perms = new_perms
        
    # Build the superpermutation string
    if not perms:
        return ""
        
    word = list(perms[0])
    
    for i in range(1, len(perms)):
        current = perms[i]
        # Find maximum overlap with the end of the current word
        # The overlap must be a suffix of word and prefix of current
        # Max possible overlap is n-1
        max_overlap = n - 1
        added = 0
        found = False
        for k in range(max_overlap, -1, -1):
            if k == 0:
                # No overlap
                word.extend(current)
                added = n
                found = True
                break
            else:
                suffix = word[-k:]
                prefix = list(current[:k])
                if suffix == prefix:
                    # Append the rest
                    word.extend(current[k:])
                    added = n - k
                    found = True
                    break
        
        if not found:
            # Should not happen if k=0 is checked
            word.extend(current)
            
    return "".join(map(str, word))
